"""Meridian CRM RBAC permission check migrated from SYSTEM_OVERVIEW.md §5."""


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether *user* may perform *action* on *object* and *record*.

    Permission rows are evaluated in their supplied order. A missing matching
    role/object/action row denies access.
    """
    role_id = user.get("ROLE_ID", "")

    matching_scope = None
    for row in role_rows:
        if (
            row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            matching_scope = row.get("scope", "")
            break

    # Missing permission rows deny, including for ADMIN.
    if matching_scope is None:
        return False

    # DELETE is only permitted for currently soft-deletable records.
    # Legacy blank CHAR(1) booleans mean N.
    if action == "DELETE" and record.get("DEL_FLG", "") not in ("", "N"):
        return False

    # ADMIN bypasses scope only after a matching object/action row exists.
    if role_id == "ADMIN":
        return True

    if matching_scope == "ALL":
        return True
    if matching_scope == "TEAM":
        return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
    if matching_scope == "OWN":
        return record.get("OWNER_UID", "") == user.get("USR_ID", "")

    # NONE and unrecognized scopes deny by default.
    return False
```

